/**
 *
 * MenuPopup is a component that displays the popup content of a menu.
 *
 * [Live Demo](https://www.primereact.org/menu/)
 *
 * @module MenuPopup
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseMotionProps } from '@primereact/types/headless/motion';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MenuRootInstance } from './MenuRoot.types';
/**
 * Defines passthrough(pt) options type in MenuPopup component.
 */
export type MenuPopupPassThroughType<E> = PassThroughType<MenuPopupInstance, E>;
/**
 * Defines passthrough(pt) options of MenuPopup component.
 */
export interface MenuPopupPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: MenuPopupPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in MenuPopup component.
 */
export interface MenuPopupProps extends BaseComponentProps<MenuPopupInstance, unknown, MenuPopupPassThrough> {
    /**
     * Used to apply motion to the popup element. It accepts the same properties as useMotion hook.
     */
    motionProps?: UseMotionProps | undefined;
}
/**
 * Defines valid state in MenuPopup component.
 */
export interface MenuPopupState {
}
/**
 * Defines the methods and properties exposed by MenuPopup component.
 */
export interface MenuPopupExposes {
    /**
     * The Menu component instance.
     */
    menu: MenuRootInstance | undefined | null;
}
/**
 * Instance of MenuPopup component.
 */
export type MenuPopupInstance = ComponentInstance<MenuPopupProps, MenuPopupState, MenuPopupExposes>;
